const i=[{id:"beta-blockers-diuretics-001",topicId:"beta-blockers-diuretics",question:"Помимо снижения артериального давления, при каком состоянии применяются бета-блокаторы?",options:["При тахикардии","При брадикардии","При анемии","При гипотонии"],correctIndex:0,explanation:"Помимо снижения артериального давления, бета-блокаторы используются при тахикардии, так как снижают частоту и силу сердечных сокращений.",difficulty:"medium",tags:["бета-блокаторы","тахикардия","применение"]},{id:"beta-blockers-diuretics-002",topicId:"beta-blockers-diuretics",question:"Как бета-блокаторы влияют на работу сердца?",options:["Снижают частоту и силу сердечных сокращений","Повышают частоту и силу сердечных сокращений","Увеличивают объём циркулирующей крови","Расширяют коронарные артерии без влияния на ритм"],correctIndex:0,explanation:"Бета-блокаторы снижают частоту и силу сердечных сокращений, что используется при тахикардии и для снижения АД.",difficulty:"medium",tags:["бета-блокаторы","механизм"]},{id:"beta-blockers-diuretics-003",topicId:"beta-blockers-diuretics",question:"К чему может привести чрезмерное применение бета-блокаторов?",options:["К гипотонии и брадикардии","К гипертензии и тахикардии","К повышению уровня калия","К отёкам и задержке жидкости"],correctIndex:0,explanation:"Чрезмерное применение бета-блокаторов может привести к гипотонии и брадикардии.",difficulty:"medium",tags:["бета-блокаторы","передозировка","брадикардия"]},{id:"beta-blockers-diuretics-004",topicId:"beta-blockers-diuretics",question:"Какой из перечисленных препаратов является бета-блокатором?",options:["Метопролол","Фуросемид","Эналаприл","Нифедипин"],correctIndex:0,explanation:"Метопролол — бета-блокатор. Фуросемид — диуретик, эналаприл — ингибитор АПФ, нифедипин — блокатор кальциевых каналов.",difficulty:"medium",tags:["бета-блокаторы","метопролол","классификация"]},{id:"beta-blockers-diuretics-005",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается пропранолол?",options:["Анаприлин","Эгилок","Конкор","Небилет"],correctIndex:0,explanation:"Пропранолол (10 мг, 40 мг) выпускается под торговым названием Анаприлин.",difficulty:"hard",tags:["бета-блокаторы","пропранолол","анаприлин"]},{id:"beta-blockers-diuretics-006",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается метопролол?",options:["Эгилок","Анаприлин","Конкор","Небилет"],correctIndex:0,explanation:"Метопролол (25, 50, 100 мг) выпускается под торговым названием Эгилок.",difficulty:"hard",tags:["бета-блокаторы","метопролол","эгилок"]},{id:"beta-blockers-diuretics-007",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается бисопролол?",options:["Конкор","Эгилок","Анаприлин","Небилет"],correctIndex:0,explanation:"Бисопролол (2,5; 5; 10 мг) выпускается под торговым названием Конкор.",difficulty:"hard",tags:["бета-блокаторы","бисопролол","конкор"]},{id:"beta-blockers-diuretics-008",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается небиволол?",options:["Небилет","Конкор","Эгилок","Анаприлин"],correctIndex:0,explanation:"Небиволол (5, 10 мг) выпускается под торговым названием Небилет.",difficulty:"hard",tags:["бета-блокаторы","небиволол","небилет"]},{id:"beta-blockers-diuretics-009",topicId:"beta-blockers-diuretics",question:"Какой из перечисленных бета-блокаторов выпускается в дозировках 50 и 100 мг?",options:["Атенолол","Бисопролол","Небиволол","Карведилол"],correctIndex:0,explanation:"Атенолол выпускается в дозировках 50 и 100 мг.",difficulty:"hard",tags:["бета-блокаторы","атенолол","дозировка"]},{id:"beta-blockers-diuretics-010",topicId:"beta-blockers-diuretics",question:"Какой из перечисленных препаратов является бета-блокатором?",options:["Карведилол","Спиронолактон","Индапамид","Каптоприл"],correctIndex:0,explanation:"Карведилол (6,25; 12,5; 25 мг) — бета-блокатор. Спиронолактон и индапамид — диуретики, каптоприл — ингибитор АПФ.",difficulty:"medium",tags:["бета-блокаторы","карведилол","классификация"]},{id:"beta-blockers-diuretics-011",topicId:"beta-blockers-diuretics",question:"Каким ещё действием, помимо снижения АД, обладают диуретики?",options:["Противоотёчным","Кровоостанавливающим","Обезболивающим","Жаропонижающим"],correctIndex:0,explanation:"Помимо снижения артериального давления, диуретики обладают противоотёчным действием.",difficulty:"medium",tags:["диуретики","противоотёчное","применение"]},{id:"beta-blockers-diuretics-012",topicId:"beta-blockers-diuretics",question:"Что такое отёк?",options:["Скопление жидкости в тканях организма","Снижение уровня калия в крови","Повышение артериального давления","Нарушение сердечного ритма"],correctIndex:0,explanation:"Отёк — это скопление жидкости в тканях организма.",difficulty:"easy",tags:["диуретики","отёк","определение"]},{id:"beta-blockers-diuretics-013",topicId:"beta-blockers-diuretics",question:"Применяются ли диуретики только при заболеваниях сердечно-сосудистой системы?",options:["Нет, их применяют и при заболеваниях других систем организма","Да, только при заболеваниях ССС","Да, только при гипертензии","Нет, их применяют только при анемии"],correctIndex:0,explanation:"Диуретики применяются не только при заболеваниях сердечно-сосудистой системы, но и при заболеваниях других систем организма.",difficulty:"medium",tags:["диуретики","применение"]},{id:"beta-blockers-diuretics-014",topicId:"beta-blockers-diuretics",question:"Снижение уровня какого электролита возможно при длительном применении фуросемида или торасемида?",options:["Калия (K)","Натрия (Na)","Кальция (Ca)","Железа (Fe)"],correctIndex:0,explanation:"При длительном применении фуросемида или торасемида возможно снижение уровня калия (K) в организме — гипокалиемия.",difficulty:"hard",tags:["диуретики","гипокалиемия","калий"]},{id:"beta-blockers-diuretics-015",topicId:"beta-blockers-diuretics",question:"Что такое гипокалиемия?",options:["Снижение уровня калия в крови","Повышение уровня калия в крови","Снижение уровня кальция в крови","Скопление жидкости в тканях"],correctIndex:0,explanation:"Гипокалиемия — это снижение уровня калия в крови.",difficulty:"medium",tags:["диуретики","гипокалиемия","определение"]},{id:"beta-blockers-diuretics-016",topicId:"beta-blockers-diuretics",question:"Какие препараты рекомендуется назначать для восстановления пониженного уровня калия?",options:["Панангин, Хлорид калия, Оротат калия","Лазикс, Гипотиазид, Диакарб","Конкор, Эгилок, Небилет","Аспирин, Плавикс, Гепарин"],correctIndex:0,explanation:"Для восстановления пониженного содержания калия рекомендуется назначать препараты калия: Панангин, Хлорид калия, Оротат калия.",difficulty:"hard",tags:["диуретики","препараты калия","Панангин"]},{id:"beta-blockers-diuretics-017",topicId:"beta-blockers-diuretics",question:"Какие последствия со стороны сердца может вызвать гипокалиемия?",options:["Аритмии и брадикардию","Повышение АД и тахикардию","Гипертрофию левого желудочка","Стенокардию напряжения"],correctIndex:0,explanation:"Последствия гипокалиемии включают аритмии и брадикардию; в тяжёлых случаях гипокалиемия может привести к остановке сердца.",difficulty:"hard",tags:["диуретики","гипокалиемия","аритмия"]},{id:"beta-blockers-diuretics-018",topicId:"beta-blockers-diuretics",question:"Какое последствие со стороны мышц характерно для гипокалиемии?",options:["Мышечная слабость, судороги, при тяжёлой форме — паралич дыхательных мышц","Усиление мышечного тонуса и силы","Гипертрофия скелетных мышц","Полное отсутствие любых мышечных симптомов"],correctIndex:0,explanation:"При гипокалиемии наблюдаются мышечная слабость, судороги, а при тяжёлой форме — паралич дыхательных мышц.",difficulty:"hard",tags:["диуретики","гипокалиемия","мышцы"]},{id:"beta-blockers-diuretics-019",topicId:"beta-blockers-diuretics",question:"Какое наиболее опасное последствие может вызвать гипокалиемия?",options:["Остановку сердца","Лёгкое головокружение","Временную потерю аппетита","Повышение температуры тела"],correctIndex:0,explanation:"Опасность гипокалиемии в том, что она может привести к остановке сердца.",difficulty:"medium",tags:["диуретики","гипокалиемия","остановка сердца"]},{id:"beta-blockers-diuretics-020",topicId:"beta-blockers-diuretics",question:"Какие последствия со стороны кишечника характерны для гипокалиемии?",options:["Запоры, атония кишечника","Диарея и обезвоживание","Усиление перистальтики","Кишечное кровотечение"],correctIndex:0,explanation:"Последствия гипокалиемии со стороны ЖКТ — запоры и атония кишечника.",difficulty:"hard",tags:["диуретики","гипокалиемия","кишечник"]},{id:"beta-blockers-diuretics-021",topicId:"beta-blockers-diuretics",question:"Какие нарушения мочеотделения и кислотно-щелочного баланса возможны при гипокалиемии?",options:["Полиурия и метаболический алкалоз","Олигурия и метаболический ацидоз","Анурия и дыхательный ацидоз","Никтурия и респираторный алкалоз"],correctIndex:0,explanation:"При гипокалиемии возможны полиурия и метаболический алкалоз.",difficulty:"hard",tags:["диуретики","гипокалиемия","полиурия"]},{id:"beta-blockers-diuretics-022",topicId:"beta-blockers-diuretics",question:"Что такое парестезии, наблюдаемые при гипокалиемии?",options:["Ощущение «мурашек» на коже","Сильная острая боль в груди","Потеря сознания","Повышение температуры"],correctIndex:0,explanation:"При гипокалиемии возникают парестезии — ощущение «мурашек», а также снижение рефлексов, апатия и сонливость.",difficulty:"medium",tags:["диуретики","гипокалиемия","парестезии"]},{id:"beta-blockers-diuretics-023",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается фуросемид?",options:["Лазикс","Гипотиазид","Верошпирон","Индап"],correctIndex:0,explanation:"Фуросемид (20, 40 мг) выпускается под торговым названием Лазикс.",difficulty:"hard",tags:["диуретики","фуросемид","лазикс"]},{id:"beta-blockers-diuretics-024",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается спиронолактон?",options:["Верошпирон","Лазикс","Гипотиазид","Диакарб"],correctIndex:0,explanation:"Спиронолактон (25, 50, 100 мг) выпускается под торговым названием Верошпирон.",difficulty:"hard",tags:["диуретики","спиронолактон","верошпирон"]},{id:"beta-blockers-diuretics-025",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается гидрохлортиазид?",options:["Гипотиазид","Лазикс","Верошпирон","Индап"],correctIndex:0,explanation:"Гидрохлортиазид (12,5; 25; 100 мг) выпускается под торговым названием Гипотиазид.",difficulty:"hard",tags:["диуретики","гидрохлортиазид","гипотиазид"]},{id:"beta-blockers-diuretics-026",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается индапамид?",options:["Индап","Гипотиазид","Лазикс","Маннит"],correctIndex:0,explanation:"Индапамид (1,25; 2,5 мг) выпускается под торговым названием Индап.",difficulty:"hard",tags:["диуретики","индапамид","индап"]},{id:"beta-blockers-diuretics-027",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается ацетазоламид?",options:["Диакарб","Лазикс","Росемид","Маннит"],correctIndex:0,explanation:"Ацетазоламид (250 мг) выпускается под торговым названием Диакарб.",difficulty:"hard",tags:["диуретики","ацетазоламид","диакарб"]},{id:"beta-blockers-diuretics-028",topicId:"beta-blockers-diuretics",question:"Под каким торговым названием выпускается торасемид?",options:["Росемид","Лазикс","Гипотиазид","Индап"],correctIndex:0,explanation:"Торасемид (5, 10 мг) выпускается под торговым названием Росемид.",difficulty:"hard",tags:["диуретики","торасемид","росемид"]},{id:"beta-blockers-diuretics-029",topicId:"beta-blockers-diuretics",question:"Какой диуретик выпускается под торговым названием Маннит в дозировках 200 и 400 мл?",options:["Маннитол","Фуросемид","Индапамид","Спиронолактон"],correctIndex:0,explanation:"Маннитол (200 мл, 400 мл) выпускается под торговым названием Маннит.",difficulty:"hard",tags:["диуретики","маннитол","маннит"]},{id:"beta-blockers-diuretics-030",topicId:"beta-blockers-diuretics",question:"Какой из перечисленных препаратов является диуретиком, а не бета-блокатором?",options:["Гидрохлортиазид","Атенолол","Метопролол","Бисопролол"],correctIndex:0,explanation:"Гидрохлортиазид — диуретик. Атенолол, метопролол и бисопролол — бета-блокаторы.",difficulty:"medium",tags:["диуретики","классификация","гидрохлортиазид"]},{id:"beta-blockers-diuretics-031",topicId:"beta-blockers-diuretics",question:"Какой комбинированный диуретический препарат содержит триамтерен и гидрохлортиазид?",options:["Триамтерен + гидрохлортиазид (25 мг/12,5 мг)","Спиронолактон + фуросемид","Индапамид + маннитол","Ацетазоламид + торасемид"],correctIndex:0,explanation:"Среди диуретиков указана комбинация триамтерен + гидрохлортиазид в дозировке 25 мг/12,5 мг.",difficulty:"hard",tags:["диуретики","комбинации","триамтерен"]},{id:"beta-blockers-diuretics-032",topicId:"beta-blockers-diuretics",question:"Почему при приёме фуросемида важно контролировать уровень калия?",options:["Потому что фуросемид может вызвать гипокалиемию, опасную остановкой сердца","Потому что фуросемид повышает уровень калия до опасных значений","Потому что фуросемид снижает уровень железа","Потому что фуросемид повышает свёртываемость крови"],correctIndex:0,explanation:"Фуросемид при длительном применении снижает калий (гипокалиемия), последствия которой включают аритмии, мышечную слабость и опасность остановки сердца; поэтому назначают препараты калия.",difficulty:"medium",tags:["диуретики","фуросемид","гипокалиемия","клиника"]},{id:"beta-blockers-diuretics-033",topicId:"beta-blockers-diuretics",question:"Какие неврологические проявления характерны для гипокалиемии?",options:["Снижение рефлексов, апатия, сонливость","Повышение рефлексов и возбуждение","Полная потеря зрения","Резкое улучшение памяти"],correctIndex:0,explanation:"При гипокалиемии наблюдаются парестезии, снижение рефлексов, апатия и сонливость.",difficulty:"hard",tags:["диуретики","гипокалиемия","неврология"]}];export{i as default};
